-- Repoints creature_template.faction for the specific Elwynn NPCs that
-- belong to a player-visible custom WorldFaction (data/elwynn/factions/
-- README.md) onto this content's own custom FactionTemplate.dbc clone
-- (data/elwynn/factions/faction_templates.csv, generated by
-- tools/dbc/build_elwynn_factions.py). Every clone copies its source
-- template's Flags/FactionGroup/FriendGroup/EnemyGroup/Enemies/Friend
-- byte-for-byte - only Faction changes (points at 1201-1204 instead of the
-- vanilla Faction id) - so current combat/aggro reaction is unchanged for
-- every entry touched here.
--
-- entry -> (old faction_template_id -> new custom id) mapping is exactly
-- data/elwynn/factions/world_faction_assignments.csv's own current_faction_
-- template_id column, cross-checked against faction_templates.csv's own
-- source_template_id -> id mapping - not hand-picked. Regenerate this
-- migration from those two CSVs if either ever changes.
--
-- Fail-closed WHERE clause: every statement also requires
-- `faction = <old source id>` so a row some OTHER change already
-- repointed away from the expected vanilla value is left untouched
-- (silently skipped) rather than forced - the same "never overwrite
-- unexpected drift" discipline this project's own C++ migrations already
-- apply to ai_agents.
--
-- IMPORTANT: FactionTemplate 7 is SHARED - Defias Thug/Garrick Padfoot/
-- James Clark move to the new clone (2300), but Porcine Entourage (390)
-- and Princess (330) are NEUTRAL_UNAFFILIATED fauna on the SAME FT 7 and
-- are deliberately NOT included below; they stay on vanilla FT 7 unchanged.

-- DEFIAS_BROTHERHOOD: FT 7 (shared, only these 3 entries) -> 2300
UPDATE `creature_template` SET `faction` = 2300
WHERE `entry` IN (38, 103, 13159) AND `faction` = 7;

-- DEFIAS_BROTHERHOOD: FT 17 (used exclusively by these 10 entries) -> 2301
UPDATE `creature_template` SET `faction` = 2301
WHERE `entry` IN (116, 94, 474, 61, 6927, 99, 473, 880, 881, 6093) AND `faction` = 17;

-- DEFIAS_BROTHERHOOD: FT 27 (used exclusively by this 1 entry) -> 2302
UPDATE `creature_template` SET `faction` = 2302
WHERE `entry` IN (6846) AND `faction` = 27;

-- ELWYNN_MURLOCS: FT 18 (used exclusively by these 4 entries) -> 2303
UPDATE `creature_template` SET `faction` = 2303
WHERE `entry` IN (46, 732, 285, 735) AND `faction` = 18;

-- RIVERPAW_GNOLLS: FT 20 (used exclusively by these 5 entries) -> 2304
UPDATE `creature_template` SET `faction` = 2304
WHERE `entry` IN (478, 97, 100, 472, 448) AND `faction` = 20;

-- ELWYNN_KOBOLDS: FT 25, enemy_group=0 (used exclusively by these 3 entries) -> 2305
UPDATE `creature_template` SET `faction` = 2305
WHERE `entry` IN (257, 6, 80) AND `faction` = 25;

-- ELWYNN_KOBOLDS: FT 26, enemy_group=PLAYER (used exclusively by these 6 entries) -> 2306
UPDATE `creature_template` SET `faction` = 2306
WHERE `entry` IN (40, 475, 476, 60, 79, 327) AND `faction` = 26;
